<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,allPages,download,fmtDate} from '../services/api';import {usePage} from '../services/usePage';import {useAuth} from '../stores/auth';import Notice from '../components/Notice.vue';import EmptyState from '../components/EmptyState.vue';import {Boxes,Check,Download} from 'lucide-vue-next'
const rows=ref<any[]>([]),auth=useAuth();const {error,success,busy,act}=usePage();const load=async()=>{rows.value=await allPages('models/')};onMounted(()=>act(load));const activate=(id:string)=>act(async()=>{await api.post(`models/${id}/activate/`);await load()},'Modelo activado para nuevas inspecciones.')
</script>
<template><h1 class="heading">Modelos con trazabilidad</h1><p class="subheading mb-7">Compara las métricas de validación. La activación requiere revisión del administrador.</p><Notice :error="error" :success="success"/><div v-if="rows.length" class="grid gap-5 md:grid-cols-2"><section v-for="m in rows" :key="m.id" class="card" :class="m.active?'!border-emerald-400':''"><div class="flex items-center justify-between"><Boxes class="text-emerald-700"/><span v-if="m.active" class="badge !bg-emerald-50 !text-emerald-700">Modelo activo</span></div><h2 class="mt-4 text-lg font-semibold">{{m.name}}</h2><p class="mt-1 text-xs text-slate-400">{{fmtDate(m.created_at)}}</p><div class="my-5 grid grid-cols-2 gap-2"><div v-for="(value,key) in m.metrics" :key="key" class="rounded-lg bg-slate-50 p-3"><p class="text-[10px] text-slate-500">{{key}}</p><p class="mt-1 text-sm font-semibold">{{Number(value).toFixed(4)}}</p></div></div><p class="mb-4 break-all text-[10px] text-slate-400">SHA-256 · {{m.sha256}}</p><div class="flex gap-2"><button class="btn-secondary" @click="act(()=>download(`models/${m.id}/download/`,'modelo-rona.pt'))"><Download :size="15"/>Pesos</button><button v-if="auth.user?.administrator&&!m.active" class="btn" :disabled="busy" @click="activate(m.id)"><Check :size="15"/>Activar modelo</button></div></section></div><EmptyState v-else title="Aún no hay modelos entrenados" text="Los pesos y las métricas aparecerán aquí cuando termine un entrenamiento real."/></template>
